import os
from azure.ai.documentintelligence import DocumentIntelligenceClient
from azure.core.credentials import AzureKeyCredential

def get_document_client():
    return DocumentIntelligenceClient(
        os.getenv('DOCUMENT_INTELLIGENCE_ENDPOINT'),
        AzureKeyCredential(os.getenv('DOCUMENT_INTELLIGENCE_API_KEY'))
    )

from typing import Any, Dict

def normalize_payload(payload: Dict[str, Any]) -> Dict[str, Any]:
    return {
        'document_bytes': payload['document_bytes'],
        'mime_type': payload.get('mime_type', 'application/pdf')
    }

def normalize_response(response: Dict[str, Any]) -> Dict[str, Any]:
    return response

import re

def extract_fields(text):
    fields = {}
    # Example regex for extracting fields (to be expanded based on actual requirements)
    field_regex = re.compile(r'(\w+)\s*:\s*(\w+)')
    matches = field_regex.findall(text)
    for match in matches:
        fields[match[0]] = match[1]
    return fields

import os
from sentence_transformers import SentenceTransformer

def embed_text(text):
    model = SentenceTransformer(os.getenv('SENTENCE_TRANSFORMERS_MODEL'))
    embeddings = model.encode(text)
    return embeddings.tolist()
